SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷78·晋高祖纪·天福四年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/37303c8175d575410e0f8940236014136161b5a6/content/books/zizhi-tongjian/vol-282/year-0939/part-05/sources/library/jiuwudaishi-078-december/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年十二月，段落 jiu-wudaishi-205deb4a7860-p001939；已核上下文及传主，纸本及异文待核。", "id": "2a30ef02-f553-50ce-8f38-34a5a76d66f7"}, {"title": "旧五代史·卷78·晋高祖纪·天福四年八月后续", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/37303c8175d575410e0f8940236014136161b5a6/content/books/zizhi-tongjian/vol-282/year-0939/part-05/sources/library/jiuwudaishi-078-late-august/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年八月后续，段落 jiu-wudaishi-205deb4a7860-p001936；已核上下文及传主，纸本及异文待核。", "id": "5adb3ab0-8d3c-5b3d-8687-fa72b2021963"}, {"title": "宋史·卷480·钱俶传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/37303c8175d575410e0f8940236014136161b5a6/content/books/zizhi-tongjian/vol-282/year-0939/part-05/sources/library/songshi-480-qian-chu/source.txt", "note": "《宋史》卷480·钱俶传，段落 songshi-9c6e46fee832-p075024；已核上下文及传主，纸本及异文待核。", "id": "d10dd84c-6dd4-553e-ae15-6268478576f6"}, {"title": "资治通鉴·后晋纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/edf81ef2a20318750c60f3a1d5fdfb06de275ef4/content/books/zizhi-tongjian/vol-282/year-0939/part-04/sources/library/tongjian-282-939-autumn/source.txt", "note": "《资治通鉴》后晋纪三，段落 zizhi-tongjian-a63549944a71-p003351；电子底本待考，分段待核", "id": "ae1a99c8-e99c-5cab-8102-be9be479d9f7"}, {"title": "新五代史·卷六十五", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8cdf5b01/content/books/zizhi-tongjian/vol-270/year-0917/part-01/sources/library/xinwudaishi-065-dayue-founding/source.txt", "note": "《新五代史》卷六十五，段落 xin-wudaishi-b08f244b9241-p003263；EPUB电子本，纸本及异文待核", "id": "fc466346-319d-55da-8b0e-c53f47717a87"}]'::jsonb)
