INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "李从益", "aliases": ["李從益"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李从益，获许王爵者。", "biography": null, "status": "draft", "id": "2d5dc982-595f-53af-8762-1255e0d9723d"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "王淑妃", "aliases": ["花见羞", "花見羞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王淑妃，为求出所借宫中渠道。", "biography": null, "status": "draft", "id": "db6392e5-1b9a-5a9d-a338-bcfe97719238"}, {"name": "郑元弼", "aliases": ["鄭元弼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国礼部员外郎。939年奉王继恭的表章，随卢损前往后晋进贡。生卒年未载。", "biography": null, "status": "draft", "id": "a656f099-5f42-574b-bfa0-daa89cb73913"}, {"name": "王继鹏", "aliases": ["王繼鵬", "王昶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继鹏，被任命权军府事的王子。", "biography": null, "status": "draft", "id": "94e0308c-1642-5beb-9233-76f848fff4f0"}, {"name": "林恩（闽进奏官）", "aliases": ["林恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国进奏官。938年十一月受王继鹏派遣，向后晋执政官转达拒绝册命和使者的意见。生卒年未载。", "biography": null, "status": "draft", "id": "73672be9-5a93-588b-9b22-1ea5a804738a"}, {"name": "李知损", "aliases": ["李知損"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋兵部员外郎。939年主张扣留闽国使者并没收货物，随后郑元弼、林恩被投入监狱。生卒年未载。", "biography": null, "status": "draft", "id": "cb0b7830-797e-5e90-b3db-da8cd826701f"}, {"name": "马氏（钱传瓘妻）", "aliases": ["恭穆夫人马氏"], "era": "五代十国", "birth_year": null, "death_year": 939, "description": "吴越王钱传瓘的妻子，雄武节度使马绰之女，称恭穆夫人。她曾为钱传瓘向钱镠请求纳妾，待各妾所生子女慈爱如一。939年去世，生年未载。", "biography": null, "status": "draft", "id": "b4c46829-8997-5bd0-8517-29ab9302032a"}, {"name": "马绰", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：马绰。", "biography": null, "status": "draft", "id": "f22273f2-c263-569e-a432-2cbe42230167"}, {"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "钱弘僔", "aliases": ["弘僔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越王钱元瓘的儿子。937年四月被立为世子。", "biography": null, "status": "draft", "id": "b277fec5-6d3f-50f1-9151-ce20879f41b3"}, {"name": "鹿氏（钱传瓘妾）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘的妾，钱弘僔、钱弘倧之母。个人名字及生卒年未载。", "biography": null, "status": "draft", "id": "cc23f887-d515-5a2c-a658-3ce607a4ca8b"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "许氏（钱传瓘妾）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘的妾，钱弘佐之母。个人名字及生卒年未载。", "biography": null, "status": "draft", "id": "7268ba47-c6ea-5d90-ab5b-71f0b619c707"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "吴氏（钱传瓘妾）", "aliases": ["恭懿夫人吴氏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘的妾，钱弘俶之母。《宋史》称其为吴越国恭懿夫人吴氏。个人名字及生卒年暂未核实。", "biography": null, "status": "draft", "id": "0df60981-eed1-5cb2-aac1-1cfcaed0a3cf"}, {"name": "钱弘偡", "aliases": ["錢弘偡"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "3f79e7fa-dab3-5ae6-a676-afd459139bb9"}, {"name": "钱弘亿", "aliases": ["錢弘億"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "11129a7d-ca77-5d63-b3fd-b341fb184b7e"}, {"name": "钱弘仪", "aliases": ["錢弘儀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "49f98e34-f2b7-5e19-add0-5bf28e618219"}, {"name": "钱弘偓", "aliases": ["錢弘偓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "f3f11efe-898d-5061-ade2-2e5efdfc46d0"}, {"name": "钱弘仰", "aliases": ["錢弘仰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "991639da-8222-59b3-a5d0-0a8575724207"}, {"name": "钱弘信", "aliases": ["錢弘信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "134304f7-fa14-59c7-a870-4a57bcb41a1f"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "遥折（契丹使者）", "aliases": ["遥折"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹臣属。939年十一月奉使后晋，随后前往吴越。姓名字形及具体官职尚待其他版本核对，生卒年未载。", "biography": null, "status": "draft", "id": "03fa2ac7-c1b9-5600-a56a-8942a5e17930"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "拓跋恒", "aliases": ["元恒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：拓跋恒，楚国仆射获任者。", "biography": null, "status": "draft", "id": "a53a8f9a-f7db-5e25-b74c-4b81973658e7"}, {"name": "李弘皋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚王马希范的幕僚，939年天策府开府时获任学士。生卒年未载。", "biography": null, "status": "draft", "id": "87806f3c-0c40-510b-b333-2e0b18bc54da"}, {"name": "廖匡图", "aliases": ["廖匡圖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚王马希范的幕僚，939年天策府开府时获任学士。与廖匡齐是否有亲属关系本段未载，不因近名建立关系。生卒年未载。", "biography": null, "status": "draft", "id": "8a82ad3a-e5fa-5b3c-b014-7342810d676c"}, {"name": "徐仲雅", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚王马希范的幕僚，939年天策府开府时获任学士。生卒年未载。", "biography": null, "status": "draft", "id": "59391753-83cd-5db6-ac4a-6162aa533f37"}, {"name": "刘勍", "aliases": ["劉勍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国左静江指挥使。939年九月与决胜指挥使廖匡齐率衡山兵五千讨伐彭士愁。生卒年未载。", "biography": null, "status": "draft", "id": "f3436028-6ef5-568c-a1c1-0bec76b0ccb3"}, {"name": "彭士愁", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "溪州刺史。939年率蒋州、锦州部众一万多人进攻辰州、澧州，并向后蜀求援，未获同意。生卒年未载。", "biography": null, "status": "draft", "id": "a28c6cdb-75c0-5abc-8757-6d971634ad02"}, {"name": "廖匡齐", "aliases": ["廖匡齊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：廖匡齐，副指挥使、出斗杀敌者。", "biography": null, "status": "draft", "id": "0d79e8f1-4787-5f81-84cc-50864386544a"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "赵光裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平二年条所见人物：赵光裔。", "biography": null, "status": "draft", "id": "a81271b0-9087-5d1f-91f3-c2ad091a480c"}, {"name": "刘岩", "aliases": ["刘龑", "劉巖", "劉龑", "劉岩", "刘巖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：刘岩。", "biography": null, "status": "draft", "id": "3b676280-64ca-5ba9-b78d-c6c5f257a018"}, {"name": "李纾（南汉谏议大夫）", "aliases": ["李纾", "李紓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉谏议大夫。939年受赵光裔推荐，奉刘岩命前往楚国恢复使节往来。与他国同名官员的关系尚未核定，生卒年未载。", "biography": null, "status": "draft", "id": "c3810c08-49bc-5855-9da7-f1722f0d0e3d"}, {"name": "越国夫人马氏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明五年条所见人物：越国夫人马氏。", "biography": null, "status": "draft", "id": "39f78bc8-8bec-5a59-aed6-8e4bbfa0dac5"}, {"name": "赵损（南汉宰相）", "aliases": ["赵损", "趙損"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵光裔之子，曾任南汉翰林学士承旨、尚书左丞。赵光裔去世后，刘岩任他为门下侍郎、同平章事；本段未列任官确年。生卒年未载。", "biography": null, "status": "draft", "id": "9111fd3a-3773-5dc0-a465-20b4e6e0d27a"}]'::jsonb)
