null, "time_original": "郑元弼十月抵达前的使节使命，书信写作确日未载", "dynasty": "五代十国", "description": "王继鹏给后晋执政者的书信称，中原帝位多次变更，使闽国海路往来受阻，并要求按对等国家的礼节互通书信。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f337b15b-e362-5b78-813c-3b6f0f98aa83"}, {"title": "石敬瑭因闽书信失礼，退还贡物并命使者归国", "start_year": 939, "end_year": 939, "time_original": "939年十月壬子", "dynasty": "五代十国", "description": "石敬瑭认为闽国书信不逊，下诏退还贡物及福州、建州等地运来的物资，并命将郑元弼和进奏官林恩尽快送回。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e0086783-5132-5481-b465-a2d3a14fe407"}, {"title": "李知损建议扣留闽使，并没收货物", "start_year": 939, "end_year": 939, "time_original": "939年十月壬子退贡命令后，具体日期未载", "dynasty": "五代十国", "description": "李知损建议扣留闽使，并没收货物。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "77b26e8c-88c9-5d64-bd02-41748ab65257"}, {"title": "郑元弼、林恩被投入监狱", "start_year": 939, "end_year": 939, "time_original": "939年十月退贡及建言后，具体日期未载", "dynasty": "五代十国", "description": "郑元弼、林恩被投入监狱。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8490faa5-64dc-5bef-8699-543a2e326746"}, {"title": "吴越恭穆夫人马氏去世", "start_year": 939, "end_year": 939, "time_original": "939年十月条下，具体日期未载", "dynasty": "五代十国", "description": "吴越恭穆夫人马氏去世。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f9504cc8-b826-503b-8ef8-257061764e59"}, {"title": "钱镠曾禁止内外蓄养声妓", "start_year": null, "end_year": null, "time_original": "钱镠在位期间的追述，具体日期未载", "dynasty": "五代十国", "description": "钱镠曾禁止宫内外蓄养声妓。这里的声妓指当时的歌舞艺人。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ef679840-c47b-5e0b-82e8-0e5cf0d82c3f"}, {"title": "马氏为钱传瓘请求纳妾，钱镠同意", "start_year": null, "end_year": null, "time_original": "钱传瓘三十多岁、钱镠在位期间，具体年份未载", "dynasty": "五代十国", "description": "钱传瓘三十多岁尚无儿子，马氏为他向钱镠请求纳妾。钱镠认为她顾及家族祭祀，赞许后允许钱传瓘纳妾。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1d77ca2e-e271-53b1-9f2f-65551667ba54"}, {"title": "马氏慈爱对待钱传瓘各妾所生子女，常逗他们玩耍", "start_year": null, "end_year": null, "time_original": "马氏生前抚育钱氏子女的概述，起止年份未载", "dynasty": "五代十国", "description": "马氏慈爱对待各妾所生子女，一视同仁。她常把银鹿摆在帐前，让孩子坐在上面，逗他们玩耍。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d7f09505-53d8-5d5c-b274-e9bc35f58166"}, {"title": "契丹派遥折出使后晋，随后前往吴越", "start_year": 939, "end_year": 939, "time_original": "939年十一月戊子", "dynasty": "五代十国", "description": "契丹派遥折出使后晋，随后前往吴越。", "phases": [], "location_name": "后晋、吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "86cf1f38-bfea-5cbe-ad05-78ac6c06bf32"}, {"title": "马希范正式开天策府，任弟弟及将校为官", "start_year": 939, "end_year": 939, "time_original": "939年十一月条下，具体日期未载", "dynasty": "五代十国", "description": "马希范正式开设天策府，设置护军都尉、领军司马等官，由他的弟弟们和将校担任。", "phases": [], "location_name": "五代十国", "location_m