, "description": "马希范派人慰问廖匡齐母亲。她没有哭，告诉使者，廖氏三百口受楚王温饱之赐，全族效死仍不足报答，何况一个儿子，请楚王不必挂念。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0eb07f12-2614-533c-976f-b96c9faeab85"}, {"title": "马希范认为廖匡齐母亲贤德，厚加抚恤其家", "start_year": 939, "end_year": 939, "time_original": "939年十一月条下，具体日期未载", "dynasty": "五代十国", "description": "马希范认为廖匡齐母亲贤德，对廖家给予优厚抚恤。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ad84e204-86bc-5e06-b930-0301e217a214"}, {"title": "石敬瑭禁止新建佛教寺院", "start_year": 939, "end_year": 939, "time_original": "939年十二月丙戌；《旧五代史》另记丙辰", "dynasty": "五代十国", "description": "石敬瑭禁止新建佛教寺院。《资治通鉴》记十二月丙戌，《旧五代史》记丙辰，两书纪日不同。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "60fdf5dd-f6b3-56ca-8844-996c00a99021"}, {"title": "王延羲建新宫并迁入居住", "start_year": 939, "end_year": 939, "time_original": "939年十二月条下，具体日期未载", "dynasty": "五代十国", "description": "王延羲建新宫并迁入居住。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "12954dc0-1ad0-576b-8492-6042ff6ed9e4"}, {"title": "赵光裔劝刘岩恢复与楚国的使节往来，并推荐李纾", "start_year": 939, "end_year": 939, "time_original": "939年，具体月日未载", "dynasty": "五代十国", "description": "赵光裔告诉刘岩，自马皇后去世后，南汉不再向楚国派使者；亲邻的旧好不应忘记。他推荐谏议大夫李纾出使楚国。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id":