SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "石敬瑭封李从益为郇国公，令他奉后唐祭祀。", "citation": "卷282·后晋天福四年（939；九月条下）·zztj-v282-y0939-p033·原文件第38行", "note": "原文：癸未，以唐许王从益为郇国公，奉唐祀。；核对说明：唐许王指后唐宗室李从益，不是南唐封王；两书月份和旧史所附五代会要九月引文分别保留，未自行裁定。", "status": "draft", "id": "fa5cb28e-8e17-5571-a35f-3cda8bbc7e72", "subject_id": "f1c71ae7-bc69-5058-81be-c1aa8824fcd8", "source_id": "ae1a99c8-e99c-5cab-8102-be9be479d9f7"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "939年九月条下癸未；《旧五代史》本纪列于八月", "citation": "卷282·后晋天福四年（939；九月条下）·zztj-v282-y0939-p033·原文件第38行", "note": "原文：癸未，以唐许王从益为郇国公，奉唐祀。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "6c6baccc-129f-5a83-a4ba-4fce6ea2b62b", "subject_id": "f1c71ae7-bc69-5058-81be-c1aa8824fcd8", "source_id": "ae1a99c8-e99c-5cab-8102-be9be479d9f7"}, {"subject_table": "person", "field_path": "description", "claim_text": "石敬瑭：封后唐许王李从益为郇国公，令其奉后唐祭祀。", "citation": "卷282·后晋天福四年（939；九月条下）·zztj-v282-y0939-p033·原文件第38行", "note": "原文：癸未，以唐许王从益为郇国公，奉唐祀。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "3cf54497-d79d-5bfb-89af-b751a2c71060", "subject_id": "bf42d98c-7477-5be1-a767-867fe26cf617", "source_id": "ae1a99c8-e99c-5cab-8102-be9be479d9f7"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "石敬瑭：封后唐许王李从益为郇国公，令其奉后唐祭祀。", "citation": "卷282·后晋天福四年（939；九月条下）·zztj-v282-y0939-p033·原文件第38行", "note": "原文：癸未，以唐许王从益为郇国公，奉唐祀。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "d16596ba-3759-5e6a-88a8-d73067100298", "subject_id": "d3a12c77-b079-5a88-94fb-d11ad038ac19", "source_id": "ae1a99c8-e99c-5cab-8102-be9be479d9f7"}, {"subject_table": "person", "field_path": "description", "claim_text": "李从益：由后唐许王改封郇国公，奉后唐祭祀。", "citation": "卷282·后晋天福四年（939；九月条下）·zztj-v282-y0939-p033·原文件第38行", "note": "原文：癸未，以唐许王从益为郇国公，奉唐祀。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "7b528079-2369-5465-a54d-91766382cf42", "subject_id": "2d5dc982-595f-53af-8762-1255e0d9723d", "source_id": "ae1a99c8-e99c-5cab-8102-be9be479d9f7"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李从益：由后唐许王改封郇国公，奉后唐祭祀。", "citation": "卷282·后晋天福四年（939；九月条下）·zztj-v282-y0939-p033·原文件第38行", "note": "原文：癸未，以唐许王从益为郇国公，奉唐祀。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "84fa92ef-d80d-5c4c-b302-2ec7c70b310b", "subject_id": "4ab6b921-1cfa-5d86-bcf0-a06050b58b6f", "source_id": "ae1a99c8-e99c-5cab-8102-be9be479d9f7"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》本纪在八月后续记李从益封郇国公，并补以西京至德宫为庙，祭祀物品由官府供给。", "citation": "《旧五代史》卷78·晋高祖纪·天福四年八月后续，段落 jiu-wudaishi-205deb4a7860-p001936；已核上下文及传主，纸本及异文待核。", "note": "原文：癸未，封唐許王李從益為郇國公，奉唐之祀，服色旌旗一依舊制。仍以西京至德宮為廟，牲幣器服悉從官給。；核对说明：本纪所在月份与通鉴九月条下有异；官供祭物和旧制服色旌旗分别按该书补证，不补实际费用。", "status": "draft", "id": "7eafa6fa-4438-542d-a95f-7c2d0c8bb6a5", "subject_id": "f1c71ae7-bc69-5058-81be-c1aa8824fcd8", "source_id": "5adb3ab0-8d3c-5b3d-8687-fa72b2021963"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》所附《五代会要》引文称九月封郇国三千户。", "citation": "《旧五代史》卷78·晋高祖纪·天福四年八月后续，段落 jiu-wudaishi-205deb4a7860-p001936；已核上下文及传主，纸本及异文待核。", "note": "原文：〈（《五代會要》：九月，敕：「周受龍圖，立夏、殷之祀；唐膺鳳歷，開酅、介之封。乃眷前朝，載稽舊典，宜封土宇，俾奉宗祧。宜以郇國三千戶封唐許王李從益為郇國公」云。）〉；核对说明：这是旧史中的转引，不作为直接查核《五代会要》的独立书证；保留本纪八月与转引九月的差异。", "status": "draft", "id": "eee5e81d-eb7e-551e-9b81-9b5e8bb1f14d", "subject_id": "f1c71ae7-bc69-5058-81be-c1aa8824fcd8", "source_id": "5adb3ab0-8d3c-5b3d-8687-fa72b2021963"}, {"subject_table": "event", "field_path": "description", "claim_text": "李从益年幼，后晋李皇后在宫中抚养他。这里的李皇后是石敬瑭的妻子、永宁公主。", "citation": "卷282·后晋天福四年（939；九月条下）·zztj-v282-y0939-p033·原文件第38行", "note": "原文：从益尚幼，李后养从益于宫中，；核对说明：养指抚养行为，本句没有法定收养或生母记载，不新增母亲、养母关系；不与闽国李春燕混淆。", "status": "draft", "id": "4bfbc3d5-5a4e-57ac-9188-cb3d5ef23c9c", "subject_id": "bcd8b00e-a76a-5d46-98b1-340e5ce3fb80", "source_id": "ae1a99c8-e99c